const SD_DEEP_LESSONS = [
 {slug:'sd-scalability',title:'Scalability and capacity planning',category:'Foundations',level:'intermediate',summary:'Scale the constrained part of the system based on measured demand, not by adding components indiscriminately.',objectives:['Estimate average and peak request rate','Separate vertical and horizontal scaling','Find bottlenecks using latency, saturation and queue depth'],diagram:'Clients → Edge/CDN → Load balancer → Stateless API replicas → Cache / DB / Queue\n                                  └→ Metrics, logs and traces at each boundary',requirements:['Functional: core read/write flows and consistency expectations','Non-functional: p95/p99 latency, availability, durability, throughput and cost','Estimate users × actions per user ÷ seconds, then state peak factor explicitly'],capacity:'Illustrative exercise: 1,000,000 daily active users × 20 requests/day = 20M requests/day ≈ 231 average RPS. At a 5× peak factor, design around 1,155 RPS before adding headroom. State whether the count includes background jobs and retries.',api:'Define read/write endpoints and explicit timeouts. Use cursor pagination for large collections. Keep stateless API nodes replaceable.',schema:'Measure request rate, payload size, active connections, DB query cost, queue wait and p95/p99 latency. Record assumptions beside every estimate.',tradeoffs:['Horizontal scaling improves capacity but introduces coordination and data partitioning concerns.','Caches reduce backend load but add staleness and invalidation complexity.','Autoscaling reacts after a signal; it cannot fix an intrinsically slow query or dependency.'],failures:['Traffic spike exhausts connection pools','One hot tenant saturates a shard','Retry storms amplify a partial outage'],source:'https://github.com/donnemartin/system-design-primer',videoQuery:'system design scalability capacity planning QPS tutorial'},
 {slug:'sd-caching',title:'Caching strategies and invalidation',category:'Performance',level:'intermediate',summary:'Choose cache placement, freshness, eviction and stampede protection around the access pattern.',objectives:['Compare cache-aside, write-through and write-behind','Define cache keys and TTL policy','Prevent stale data, stampedes and hot-key overload'],diagram:'Read: API → Cache hit ───────────────→ response\n                └ miss → Database → set cache → response\nWrite: API → Database commit → invalidate/update cache',requirements:['Clarify acceptable staleness per field','Set TTL, eviction, invalidation and fallback behavior','Avoid caching personalized data without a complete authorization-aware key'],capacity:'Illustrative: 800 read RPS with an 85% hit ratio leaves about 120 RPS reaching the origin. Capacity still needs headroom for expiration bursts and cold starts.',api:'Cache keys include tenant/user scope where needed; cache-control for HTTP resources; explicit invalidation on writes.',schema:'Key: namespace:entity-id[:version]. Track hit/miss ratio, eviction, stale reads, origin load and cache latency.',tradeoffs:['Long TTL improves hit rate but increases stale windows.','Write-through simplifies reads but increases write-path dependency.','Distributed cache reduces DB load but becomes a dependency requiring timeouts and fallback.'],failures:['Cache outage overwhelms DB','Many popular keys expire simultaneously','An incomplete key leaks another user’s data'],source:'https://redis.io/docs/latest/develop/use/patterns/',videoQuery:'cache aside write through invalidation cache stampede system design'},
 {slug:'sd-load-balancing',title:'Load balancing and traffic routing',category:'Networking',level:'intermediate',summary:'Distribute traffic across healthy replicas while preserving affinity and protecting downstream dependencies.',objectives:['Compare L4 and L7 routing','Choose a balancing algorithm','Design health checks, draining and timeout budgets'],diagram:'Internet → DNS / CDN → L7 Load Balancer → API A / API B / API C\n                                  ├→ active health checks\n                                  └→ drain connections before deploy',requirements:['Health checks must represent useful readiness, not only process liveness','Set connect, request and downstream timeouts','Plan TLS termination, sticky sessions only when needed, and graceful draining'],capacity:'If each safe API replica sustains 250 RPS under target latency and measured peak is 1,000 RPS, 4 replicas are the theoretical floor; add redundancy/headroom and verify downstream capacity.',api:'External API stays stable as replicas change. Use request IDs and retry policies that do not retry non-idempotent work blindly.',schema:'Monitor healthy/unhealthy targets, 4xx/5xx rate, queue time, connection reuse, per-target latency and uneven load.',tradeoffs:['Round-robin is simple; least-connections or latency-aware routing can adapt but need trustworthy measurements.','Sticky sessions simplify in-memory state but make scaling and failover harder.','Aggressive retries may increase overload instead of healing it.'],failures:['All targets fail health checks together','Long requests prevent draining','One slow target creates tail-latency spikes'],source:'https://aws.amazon.com/what-is/load-balancing/',videoQuery:'layer 4 layer 7 load balancer health check system design'},
 {slug:'sd-replication',title:'Replication, failover and durability',category:'Storage',level:'advanced',summary:'Replicate data to improve availability and read scale while making the consistency and recovery model explicit.',objectives:['Compare synchronous and asynchronous replication','Plan primary election and failover','Explain replication lag, split-brain protection and restore testing'],diagram:'Writes → Primary → replication log → Replica A (read)\n                             └──────────→ Replica B (standby)\nFailover controller → fenced/promoted replica → route writes',requirements:['Define RPO and RTO','Specify whether read-after-write must be guaranteed','Fence old primaries and prevent two writers'],capacity:'Read replicas add read capacity only for queries that tolerate replica lag. Write throughput usually remains bounded by the write leader or partition.',api:'Use an explicit read consistency policy. Return operation IDs when callers need to poll after asynchronous durable acceptance.',schema:'Monitor replication lag, WAL/oplog growth, leader changes, failover duration, replication errors and restore success.',tradeoffs:['Synchronous replication improves durability but adds write latency and may reduce availability.','Asynchronous replication reduces latency but risks losing recent acknowledged writes in failover.','More replicas cost storage, bandwidth and operational effort.'],failures:['Replica lag causes stale authorization or booking reads','Network partition produces competing leaders','Backups exist but have never been restored'],source:'https://www.postgresql.org/docs/current/warm-standby.html',videoQuery:'database replication synchronous asynchronous failover RPO RTO'},
 {slug:'sd-sharding',title:'Sharding and partitioning',category:'Storage',level:'advanced',summary:'Partition large datasets for capacity while controlling hot keys, movement, ordering and cross-shard queries.',objectives:['Choose a stable shard key','Compare range, hash and directory-based routing','Plan rebalancing and cross-shard transactions'],diagram:'Request → shard router → hash(tenant_id) → Shard 0 / Shard 1 / Shard 2\n                                     └ hot-key metrics + resharding plan',requirements:['Choose key cardinality and write distribution','Identify query paths that need joins or global sort','Plan migration, resharding and shard failure recovery'],capacity:'For N equally sized shards, ideal per-shard data is total data ÷ N; real workloads are skewed. Plan headroom for skew, growth and rebalancing copies.',api:'Keep shard routing internal. APIs should avoid requiring callers to know physical shard IDs.',schema:'Partition by tenant/user/room only when it aligns with access patterns. Measure per-shard QPS, storage, p99 latency and key skew.',tradeoffs:['Hash sharding spreads keys but hurts range scans.','Range sharding helps ordered queries but risks hot adjacent ranges.','Cross-shard consistency and unique constraints become more complex.'],failures:['Celebrity/enterprise tenant becomes a hot shard','Resharding overloads network and disks','Shard map mismatch routes writes to the wrong owner'],source:'https://www.mongodb.com/docs/manual/sharding/',videoQuery:'database sharding shard key hot partitions resharding'},
 {slug:'sd-queues',title:'Queues, ordering and background workers',category:'Messaging',level:'intermediate',summary:'Decouple producers from consumers with explicit delivery, ordering, retry and overload contracts.',objectives:['Compare at-most-once, at-least-once and effectively-once behavior','Implement idempotent consumers and dead-letter handling','Size consumers from arrival and service rates'],diagram:'API → durable queue → consumer group → side effect / database\n               ↑ retry with backoff       └→ dead-letter queue + alert',requirements:['Choose durability, ordering scope, retention and maximum queue age','Bound retries and concurrency; classify transient vs permanent errors','Define poison-message handling and replay controls'],capacity:'If events arrive at 600/s and each worker safely processes 40/s, at least 15 workers are needed for steady-state throughput; add headroom and consider bursts and downstream quotas.',api:'Return accepted/job ID only after the durability point promised by the API. Expose status endpoints where callers need completion confirmation.',schema:'Include event_id, idempotency_key, created_at, attempt, payload_version and correlation_id. Monitor age of oldest message, redelivery and DLQ count.',tradeoffs:['More consumers improve throughput but can increase downstream saturation and ordering violations.','Long retention aids replay but increases storage and privacy obligations.','FIFO partitions trade global ordering for throughput.'],failures:['Consumer crashes after side effect before acknowledgement','Retry storm increases queue depth','Poison messages block a partition'],source:'https://docs.bullmq.io/',videoQuery:'message queues at least once delivery idempotent consumer dead letter queue'},
 {slug:'sd-consistency',title:'Consistency models and transaction boundaries',category:'Distributed systems',level:'advanced',summary:'Choose consistency semantics per operation rather than saying the whole system is simply consistent or eventual.',objectives:['Compare strong, eventual and read-your-writes guarantees','Understand atomicity and isolation anomalies','Choose sagas/outbox when work crosses services'],diagram:'Client → service transaction (business row + outbox row) → commit\n                                                  ↓ relay publishes event\nService B consumes idempotently → local transaction',requirements:['State invariants that must never be violated','Identify the true transaction boundary','Define conflict handling, retry semantics and reconciliation'],capacity:'Transaction latency includes lock waits and any synchronous coordination. Measure contention and transaction duration before increasing concurrency.',api:'Use conditional updates/version columns and idempotency keys. For multi-step workflows expose pending/succeeded/failed states rather than claiming a distributed atomic commit.',schema:'Use constraints for invariants; store outbox events in the same database transaction as the business change. Record idempotency key, result and expiry.',tradeoffs:['Strong consistency can add coordination latency.','Eventual consistency scales workflows but callers must tolerate pending/stale states.','Sagas provide compensating actions, not true rollback of every external side effect.'],failures:['Duplicate events apply a command twice','Read replica lags after a successful write','Two bookings both pass an unchecked availability read'],source:'https://www.postgresql.org/docs/current/transaction-iso.html',videoQuery:'distributed systems consistency models transactions saga outbox pattern'},
 {slug:'sd-idempotency',title:'Idempotency and safe retries',category:'Reliability',level:'intermediate',summary:'Make duplicate requests and event deliveries return one logical outcome even when the network is ambiguous.',objectives:['Distinguish idempotent request semantics from deduplication','Persist and scope an idempotency key','Handle simultaneous identical requests safely'],diagram:'Request + key → unique key claim → execute once → persist result\n                      └ duplicate/retry → return stored outcome',requirements:['Define key scope (user, endpoint, operation), retention and payload mismatch behavior','Protect simultaneous requests using a unique constraint/atomic claim','Never assume a timeout means the first operation failed'],capacity:'Size key retention to the maximum client retry and delayed-delivery window. Large key/result tables need TTL cleanup and indexed lookups.',api:'POST /payments with Idempotency-Key; same key + same request returns the original result; same key + different payload returns a conflict.',schema:'idempotency_records(key, owner_id, request_hash, state, response_code, response_body, created_at, expires_at) with unique key scope.',tradeoffs:['Long retention reduces duplicate risk but stores more data.','Caching a response before the business transaction completes can return false success.','Key reuse policy must be consistent across retries.'],failures:['Two concurrent claims both execute','Key is scoped globally and leaks another user’s result','External provider accepts payment but local response write fails'],source:'https://stripe.com/docs/api/idempotent_requests',videoQuery:'API idempotency key payment retries duplicate requests'},
 {slug:'sd-rate-limiting',title:'Rate limiting and abuse control',category:'Reliability',level:'intermediate',summary:'Protect capacity and users with limits whose scope, algorithm and failure behavior are explicit.',objectives:['Compare fixed window, sliding window, token bucket and leaky bucket','Choose per-user, tenant, IP and endpoint scopes','Handle distributed counters and graceful degradation'],diagram:'Request → identify principal → rate-limit check → allow → service\n                                     └ deny (429 + Retry-After)',requirements:['Define request cost and enforcement scope','Use a trusted identity after authentication; treat IP as a weak signal','Specify fail-open vs fail-closed behavior when the limiter is unavailable'],capacity:'Estimate peak key count and operations/sec. A centralized counter can become a hot key; sharded counters improve throughput but allow bounded approximation.',api:'Return 429 and Retry-After. For APIs with variable costs, consume weighted tokens rather than counting every request equally.',schema:'Store counter/bucket key, tokens or count, window/last-refill time and TTL. Avoid unbounded user-controlled keys.',tradeoffs:['Fixed windows are cheap but permit boundary bursts.','Sliding windows are smoother but need more state/operations.','Token buckets allow bursts while limiting long-term rate.'],failures:['Clock skew breaks window assumptions','Limiter outage cascades into the API','Untrusted forwarded IP headers allow evasion'],source:'https://redis.io/docs/latest/develop/use/patterns/rate-limiter/',videoQuery:'token bucket sliding window distributed rate limiter system design'},
 {slug:'sd-fault-tolerance',title:'Fault tolerance and graceful degradation',category:'Reliability',level:'advanced',summary:'Contain failure using budgets, bulkheads, bounded retries, circuit breakers and recovery paths.',objectives:['Use timeouts before retry policies','Avoid retry amplification and cascading failure','Define degraded-but-safe responses'],diagram:'API → deadline budget → bulkhead → dependency\n                     ├ timeout / circuit open → fallback or controlled error\n                     └ retry bounded + jitter for safe operations',requirements:['Define SLO, error budget, RTO/RPO and dependency criticality','Use request deadlines and cancellation','Separate liveness, readiness and dependency health'],capacity:'A saturated downstream with unbounded queues increases latency and memory. Bound concurrency and queue length, then shed load when capacity is exhausted.',api:'Use consistent timeout/error semantics; include a correlation ID but no secrets or internal stack traces in client responses.',schema:'Track error rate, latency percentiles, saturation, circuit state, retries, queue depth and recovery duration.',tradeoffs:['Retries help transient failures but consume capacity.','Circuit breakers reduce pressure but can reject work during recovery.','Fallback data can preserve availability at the cost of freshness/correctness.'],failures:['Retry storm after partial outage','Shared thread/connection pool causes a bulkhead collapse','Liveness checks trigger restart loops'],source:'https://aws.amazon.com/builders-library/timeouts-retries-and-backoff-with-jitter/',videoQuery:'circuit breaker bulkhead timeout retries graceful degradation system design'},
 {slug:'sd-observability',title:'Observability and operational readiness',category:'Operations',level:'intermediate',summary:'Use metrics, structured logs and traces to see system behavior and shorten diagnosis time.',objectives:['Distinguish logs, metrics and distributed traces','Choose SLI/SLO indicators','Use correlation IDs across queues and service boundaries'],diagram:'Client request_id → API span → DB span / cache span / queue publish\n                         → worker span → provider call\nMetrics + logs + traces → dashboard + alert + incident timeline',requirements:['Define user-facing SLIs and actionable alert thresholds','Propagate trace/correlation context across async messages','Redact secrets and personal data from logs'],capacity:'High-cardinality metric labels create cost and slow queries. Keep dimensions bounded; use traces/logs for per-request context.',api:'Accept or generate a request/correlation ID and pass it to downstream services and message metadata.',schema:'Structured fields: timestamp, level, service, environment, trace_id, request_id, event, duration_ms, outcome; exclude passwords/tokens.',tradeoffs:['Sampling lowers tracing cost but may miss rare failures.','More logs improve forensic detail but raise cost and privacy risk.','Alerts on symptoms are often more useful than every component anomaly.'],failures:['Clock skew breaks cross-service timelines','Logs contain access tokens','Alert floods obscure the user-facing outage'],source:'https://opentelemetry.io/docs/',videoQuery:'observability logs metrics distributed tracing SLI SLO tutorial'},
 {slug:'sd-replication-sharding',title:'Combining replication and sharding',category:'Storage',level:'advanced',summary:'Partition data for write/storage growth and replicate each partition for availability, while acknowledging both failure domains.',objectives:['Separate partition ownership from replica failover','Choose read/write routing semantics','Plan shard rebalancing and replica recovery'],diagram:'Router → Shard A primary → replicas\n       ├→ Shard B primary → replicas\n       └→ Shard C primary → replicas',requirements:['Select partition key and replica placement together','Define per-shard failover, routing and resharding procedures','Avoid a single global bottleneck in metadata and coordination'],capacity:'Ideal per-shard load is total load ÷ shard count, but skew and replication traffic need headroom. Do not assume read replicas solve write-hot partitions.',api:'Routing remains transparent; avoid contracts that expose physical shard identifiers.',schema:'Track per-shard data, QPS, lag, hot-key distribution and rebalance progress.',tradeoffs:['More shards improve parallelism but increase operations and cross-shard complexity.','Replicas improve read/availability options but consume bandwidth and may lag.','Global transactions/uniqueness need extra coordination.'],failures:['Partition router has stale shard map','One shard loses quorum','Migration dual-writes diverge'],source:'https://www.mongodb.com/docs/manual/sharding/',videoQuery:'replicated sharded database architecture tutorial'}
];
